// Temporary mock catalog — stands in for the `persons` table until the
// Supabase project exists and migration 0001 is applied. Real entries will
// carry a Wikimedia Commons portrait with author/license/source per the
// project's portrait rule; these placeholders intentionally don't, since the
// attribution data hasn't been sourced yet.
export type PersonCategory = "herec" | "hudebnik" | "sportovec" | "spisovatel" | "jine";

export type FilmographyEntry = {
  year: number;
  title: string;
  note?: string;
};

export type PriceHistoryPoint = {
  year: number;
  price: number;
};

export type SaleListing = {
  title: string;
  url: string;
};

// A person's fallback portrait, shown until someone uploads a real photo
// through the app. Two ways to get one:
//  - "wikipedia" (the default when `source` is omitted, since every entry
//    added before this field existed is one of these): a real Wikimedia
//    Commons photo, sourced and license-checked per person (never assumed
//    from a studio name alone — see the file header). `url` points at
//    Commons' own Special:FilePath redirect so we never have to guess an
//    upload.wikimedia.org hash, and hotlinking it is the reuse method
//    Wikimedia documents and expects. `author`/`license`/`sourceUrl` are
//    required for this source so the credit line has something to show.
//  - "ai": no free Commons photo exists, so the portrait was generated with
//    Adobe Firefly instead. There's no photographer or license to credit —
//    just the "Created with AI" note — so `author`/`license`/`sourceUrl`
//    don't apply and shouldn't be set.
export type PersonPortraitSource =
  | { url: string; source?: "wikipedia"; author: string; license: string; sourceUrl: string }
  | { url: string; source: "ai" };

export type MockPerson = {
  slug: string;
  name: string;
  category: PersonCategory;
  // Drives which silhouette PersonAvatar shows when there's no photo yet —
  // determined from each bio's own Czech grammatical gender (verb endings
  // like "narodil"/"narodila"), not guessed from the name.
  gender: "m" | "f";
  birthYear: number;
  deathYear: number | null;
  nationality: string;
  bio?: string;
  funFact?: string;
  funFactSourceUrl?: string;
  filmography?: FilmographyEntry[];
  marketPriceMin?: number;
  marketPriceMax?: number;
  // Flags an especially scarce autograph on the secondary market — shows a
  // "Vzácný" badge next to the price (see PersonDetailClient).
  rare?: boolean;
  priceHistory?: PriceHistoryPoint[];
  saleListings?: SaleListing[];
  portrait?: PersonPortraitSource;
};

export const CATEGORY_LABELS: Record<PersonCategory, string> = {
  herec: "Herec",
  hudebnik: "Hudebník",
  sportovec: "Sportovec",
  spisovatel: "Spisovatel",
  jine: "Jiné",
};

// Drives the catalog card price pill's color (see components/Price.tsx) —
// a price reads differently at a glance depending on which category it's
// from, rather than every card looking identical regardless of who it is.
export const CATEGORY_COLORS: Record<PersonCategory, string> = {
  herec: "#7F77DD",
  hudebnik: "#D85A30",
  sportovec: "#1D9E75",
  spisovatel: "#B08D57",
  jine: "#71717A",
};

