    bio: "Jean Marcel Lefebvre se narodil ve francouzském Valenciennes a původně studoval medicínu — studia mu ale přerušila druhá světová válka, během níž padl do zajetí. Po válce nastoupil na konzervatoř v oboru opera, zpěv ho ale nakonec nezaujal tolik jako herectví, na které se pak přeorientoval. Po škole hrál hlavně v kabaretech a před filmovou kamerou se poprvé objevil až v roce 1952, v muzikálu Bouquet po boku zpěváka Charlese Treneta. S Louisem de Funèsem se ve filmech potkával už předtím, než se z něj stala komická hvězda číslo jedna (Výhodná koupě, Gentleman z Epsomu, Jak vykrást banku), a jejich spolupráce pak vyvrcholila rolí četníka Luciena Fougasse ve čtyřech dílech slavné série o četnících ze Saint-Tropez. Za svůj život natočil přes sto dvacet filmů, přesto zůstal především divadelním hercem. Zemřel v roce 2004 v marockém Marrákeši, kde ho v jedné z restaurací postihl infarkt.",
    funFact: "Než se stal hercem, studoval postupně medicínu a operní zpěv — k herectví se dostal až jako ke třetí volbě. V soukromém životě pak sbíral svatby: celkem se ženil pětkrát a měl pět dětí, přičemž jednu z partnerek si vzal a rozvedl hned dvakrát po sobě v průběhu 70. let.",
