    birthYear: 1944,
    deathYear: 2024,
    nationality: "Francie",
    bio: "Geneviève Gradová (rodným jménem Geneviève Gabrielle Grad) se narodila v Paříži matce architektce a jako mladá dívka se připravovala na dráhu tanečnice na pařížské opeře, než ji objevili filmaři. V sedmnácti letech dostala roli Isabelle po boku Jeana Maraise ve snímku Kapitán Fracasse (1961) a o pár let později se ucházela i o hlavní roli v Angelice, markýze andělů — tu ale nakonec získala Michèle Mercier. Životní roli si nakonec přesto zahrála: rošťáckou dceru četníka Cruchota, Nicole, v prvních třech dílech slavné série o četnících ze Saint-Tropez (1964–1968). Po natáčení Četník se žení si ale uvědomila, že si dvanáct let nevzala pořádnou dovolenou, a s náhlou slávou se jí přitížilo i psychicky — z filmového světa se proto stáhla a v dalších dílech série se už neobjevila. Ještě si zahrála v pár dalších snímcích (Flash Love, Libertés sexuelles) a naposledy stanula před kamerou v roce 1983. Poté pracovala jako obchodnice se starožitnostmi a spolu s Annie Chaplin, dcerou Charlieho Chaplina, organizovala kulturní akce pro město Vendôme — a i přes odchod z veřejného života dál dostávala dopisy s žádostmi o autogram od fanoušků z celého světa. Zemřela v listopadu 2024 ve věku 80 let po dlouhém boji s rakovinou.",
    funFact: "Její zasnoubení s Olivierem de Montalem skončilo poté, co ji seznámil se svými kamarády, dvojčaty Igorem a Grichkou Bogdanoffovými, kteří tehdy žili na rodinném zámečku Saint-Lary. Geneviève se do Igora zamilovala, v roce 1976 se jim narodil syn Dimitri a nějakou dobu žila přímo na jejich panství — stala se dokonce asistentkou produkce jejich tehdy kultovního televizního pořadu Temps X, díky němuž patřili bratři Bogdanoffové k nejznámějším televizním tvářím osmdesátých let ve Francii. Vztah s Igorem ale postupem času vychladl, otcovství přestal brát vážně a se synem se dál nestýkal. Bratři se navíc proslavili i chorobnou závislostí na plastické chirurgii, kvůli které byli ke konci života téměř nepoznatelní, a zemřeli na covid jen pár dní po sobě. Dimitri sám na veřejnosti nevystupuje a není ani jisté, čí příjmení nosí. Geneviève se pak v 90. letech provdala za architekta Jeana Guillaumea, který jí zůstal po boku až do konce života.",
