    nationality: "Francie",
    bio: "France Rumilly, celým jménem Marie-Françoise Suzanne Jeanne Rumilly, se narodila v Boulogne-Billancourt. Značnou část školních let strávila v klášteře, později studovala herectví a na konkurzu ji objevil režisér Jack Pinoteau, který jí v roce 1962 svěřil roli dcery Louise de Funèse ve filmu Výhodná koupě. Nejznámější se ale stala jako sestra Klotylda, věčně rozjívená jeptiška na motorové dvoukolce Citroën 2CV, v prvních třech dílech série o četnících ze Saint-Tropez — kaskadérské scény za ni odjížděl Rémy Julienne. Objevila se i v dalších filmech s Louisem de Funèsem, například v Grand restaurantu pana Septima jako baronka. Naposledy stanula před kamerou v roce 1986 ve filmu Twist again à Moscou, ve svých sedmačtyřiceti letech. Za kariéru si zahrála přibližně v pětadvaceti filmech a v mnoha dalších dělala drobnou komparzní roli — celkem se objevila ve více než dvou stovkách filmů mezi lety 1960 a 1999.",
