    nationality: "Francie",
    bio: "Claude Gensacová vystudovala pařížskou konzervatoř dramatického umění a kariéru začínala jako tragédka — hrála Corneilla, Sartra i Giraudouxe a v roce 1962 propůjčila hlas Zlé královně v novém francouzském dabingu Disneyho Sněhurky. S Louisem de Funèsem se poprvé potkala už v roce 1952 na place Sachy Guitryho, opravdovou filmovou dvojici z nich ale udělal až rok 1967 a snímek Oskar, kde si zahrála jeho manželku — o obsazení tehdy rozhodla de Funèsova žena Jeanne, která chtěla po boku svého muže distingovanou herečku, jíž zároveň důvěřovala. Od té doby si spolu zahráli jedenáctkrát, z toho osmkrát jako filmoví manželé — mimo jiné v Senzačních prázdninách, Četníkovi se žení, Hibernatovi i Četníkovi ve výslužbě. Diváci si ji navždy spojili s postavou Josépy Cruchotové a oslovením „má laňko“, kterým ji de Funès ve filmech častoval; po jeho smrti v roce 1983 se jí dlouho nedařilo této nálepky zbavit. K výraznějším rolím se vrátila až koncem 2000. let, mimo jiné po boku Catherine Deneuveové ve filmu Ona odchází (2013), a za roli ve filmu Lulu, nahá žena (2013) dostala v sedmaosmdesáti letech nominaci na Césara pro nejlepší herečku ve vedlejší roli — nejstarší nominovanou v historii této kategorie.",
    funFact:
      "V roce 1976 ji Louis de Funès osobně prosadil do role sekretářky ve filmu Křidýlko nebo stehýnko — musela si ale nasadit šedou paruku, aby ji diváci hned nerozpoznali jako jeho „filmovou ženu“. O tři roky dřív, v pátém díle Četníků, roli Josépy kvůli divadelnímu angažmá nakonec nehrála — nahradila ji Maria Mauban.",
