    bio: "Paul Préboist vyrůstal v marseillské čtvrti La Rose, ve čtrnácti letech se živil jako žokej na překážkových dostizích a později jako přepážkový úředník na pojišťovně. Za druhé světové války vystupoval v marseillských kavárnách a nemocnicích s parodiemi na písně Fernandela — a právě tehdy si poprvé zahrál scénky s tehdy ještě neznámým Louisem de Funèsem. Po přestěhování do Paříže se prosadil v divadle i kabaretu a mezi lety 1948 a 1992 se objevil ve více než sto dvaceti filmech, většinou v komických vedlejších rolích, často po boku Louise de Funèse, s nímž se znal už z marseillských začátků. Kritikou nejceněnější roli dostal mimo komedie — jako citlivý venkovan Pascal ve snímku Dům (1970) režiséra Gérarda Bracha. Na podzim 1994 se s hereckou kariérou rozloučil a věnoval se chovu koní; zemřel o necelé tři roky později, v březnu 1997.",
