    bio: "Vlastním jménem André Raimbourg vyrůstal jako syn normandských zemědělců a uměleckou dráhu si vysnil podle svého vzoru Fernandela. Nejdřív se živil jako hudebník a šansoniér v pařížských kabaretech, po válce se stal hvězdou music-hallu s písněmi jako Les Crayons nebo pozdější Salade de fruits a À bicyclette. Na plátně si zprvu vystačil s karikaturou naivního normandského venkovana, ale dramatická role pařížského nezaměstnaného za okupace ve filmu Napříč Paříží (1956) mu vynesla cenu za herecký výkon na benátském filmovém festivalu a otevřela cestu k vážnějším rolím. V polovině 60. let ho producent Gérard Oury spároval s Louisem de Funèsem — jejich dvojice ve Smolaři (1965) a Velkém flámu (1966) patří k nejúspěšnějším francouzským filmům vůbec. Zemřel v září 1970, necelý rok po premiéře Velkého flámu, ve věku 53 let.",
