    nationality: "Francie",
    bio: "Jean Marais se proslavil už ve 30. letech jako múza a životní partner básníka a režiséra Jeana Cocteaua, který mu napsal hlavní divadelní role i filmový debut ve válečném hitu Věčný návrat (1943). S Cocteauem pak natočil své nejslavnější snímky — pohádku Kráska a zvíře (1946) i Orfea (1950). Od 50. let se stal hlavní hvězdou francouzských kostýmních dobrodružných filmů (Hrbáč, Kapitán, Kapitán Fracasse), většinu kaskadérských kousků si přitom odvážel sám, patnáct let před Jeanem-Paulem Belmondem. V 60. letech přesedlal i na moderní akční žánr ve fantomasovské trilogii, kde po boku Louise de Funèse ztvárnil dvojroli zločince a novináře Fandora. Později se věnoval hlavně divadlu a jako uznávaný keramik a sochař žil ve francouzském Vallauris. V roce 1993 dostal čestného Césara za celoživotní dílo. Zemřel v roce 1998 v Cannes ve věku 84 let.",
