    bio: "Claude Rich vystudoval pařížskou konzervatoř, kde patřil k takzvané „tlupě z konzervatoře“ spolu s budoucími hvězdami Jeanem Rochefortem, Jeanem-Paulem Belmondem, Jeanem-Pierrem Mariellem nebo Brunem Cremerem. Kariéru odstartoval už v roce 1955 ve Velkých manévrech Reného Claira a v 60. letech se etabloval jako spolehlivý herec druhých hlavních rolí — po boku Lina Ventury v Tontons flingueurs (1963) i jako mladý účetní Christian Martin čelící Louisi de Funèsovi ve filmu Oskar (1967). Jednu z nejvýraznějších rolí dostal ve sci-fi filmu Je t'aime, je t'aime (1968) Alaina Resnaise, kde si ho režisér vybral kvůli osobitému hlasu. Od 70. let se vrátil hlavně k divadlu, ale na plátně se objevoval dál až do vysokého věku, mimo jiné jako druid Panoramix v Asterixovi a Obelixovi: Mise Kleopatra (2002). Za divadelní roli Talleyranda ve hře Večeře získal Césara pro nejlepšího herce, v roce 2002 dostal i čestného Césara za celoživotní dílo. Zemřel v červenci 2017 ve věku 88 let.",
