    bio: "Yves Montand, vlastním jménem Ivo Livi, se narodil v Itálii a jako dítě uprchl s rodinou před fašismem do Marseille, kde vyrostl. Nejdřív se živil jako zpěvák v marseillských kabaretech, po válce se s podporou Édith Piaf stal hvězdou pařížského music-hallu — jeho písně Les Feuilles mortes nebo C'est si bon patří dodnes k nejznámějším francouzským šlágrům. K filmu ho hudební sláva přivedla už začátkem 50. let, skutečné herecké uznání ale přišlo až s thrillerem Mzda strachu (1953) a později s politickou trilogií režiséra Costa-Gavrase (Z, Doznání, Stav obležení), která z něj udělala tvář angažovaného kina. V roce 1971 si zahrál sluhu Blaze ve filmu Pošetilost mocných po boku Louise de Funèse — roli, kterou měl původně hrát Bourvil, než mu v tom zabránila jeho smrt na rakovinu. S herečkou Simone Signoretovou, kterou si vzal v roce 1951, tvořili jeden z nejslavnějších párů francouzského filmu. Zemřel v listopadu 1991 ve věku 70 let.",
