    nationality: "Francie",
    bio: "Michel Colucci, známý pod uměleckým jménem Coluche, vyrůstal v chudých poměrech na pařížském předměstí Montrouge — otec, italský malíř pokojů, zemřel, když mu byly tři roky, a matka živila rodinu sama. Proslavil se koncem 60. a v 70. letech jako drsný stand-up komik a rozhlasový moderátor. Ve filmu se zprvu spokojil s malými rolemi, zlom přišel v roce 1976, kdy dostal roli syna Louise de Funèse ve filmu Křidýlko nebo stehýnko — první výraznější filmová role mimo vlastní pódiové vystupování. V 80. letech se stal jednou z největších hvězd francouzské filmové komedie a za dramatickou roli ve filmu Tchao Pantin získal v roce 1984 Césara pro nejlepšího herce. Krátce kandidoval na francouzského prezidenta v roce 1981, než kandidaturu pod tlakem stáhl. V roce 1985 založil charitativní organizaci Restos du Cœur, která dodnes pomáhá lidem bez prostředků. Zemřel v červnu 1986 při nehodě na motorce ve věku 41 let.",
