    bio: "Jean Carmet pocházel z Tours, kde jeho otec vedl malou sedlářskou dílnu a vinici. Do Paříže odešel už jako mladík a živil se jako komparzista v Théâtre du Châtelet a pařížské opeře, než se přidal k divadelní tlupě Branquignols Roberta Dhéryho. Slávu mu nejdřív přinesl hlas — namluvil postavu Gastona Duveta v populárním rozhlasovém seriálu La Famille Duraton — a skutečnou filmovou celebritou se stal až v polovině 70. let, v poměrně pokročilém věku, díky filmům jako Velký blonďák s černou botou. Za víc než čtyřicet let kariéry si zahrál ve dvou stovkách filmů, od groteskních komických rolí přes drama (Dupont Lajoie) až po temného vraha z neděle v kultovním filmu Chladný bufet. V roce 1981 hrál po boku Louise de Funèse jednoho ze dvou starých venkovských kamarádů v Zelňačce. Za vedlejší role dostal dva Césary (Bídníci 1983, Merci la vie 1992) a v roce 1994, těsně před smrtí, i čestného Césara za celoživotní dílo. Zemřel v dubnu 1994 ve věku 73 let.",
