    bio: "André Isaac, uměleckým jménem Pierre Dac, byl legendární francouzský humorista, novinář a za druhé světové války i odbojář, jehož vysílání pro Radio Londres pomáhalo povzbuzovat okupovanou Francii. Ve 30. letech založil humoristický list L'Os à moelle a je autorem řady dodnes používaných výrazů a nesmyslných vynálezů, mimo jiné pojmu „loufoque“ (bláznivý) nebo fiktivního přístroje „Schmilblick“. Po válce vytvořil s Francisem Blanchem proslulé rozhlasové duo a psal a moderoval populární rozhlasové seriály jako Signé Furax. Ve filmu se objevoval jen zřídka — mimo jiné jako ministr v Tonoucím se stébla chytá (1968) po boku Louise de Funèse. Zemřel v únoru 1975 v Paříži ve věku 81 let.",
